// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { AIToolProps } from "./ai-tool.types";

import { type CSSObject } from "@emotion/react";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "AITool";

// Generate child element class names for the component, should match available style slots
export const AIToolClasses = {
  root: "exp-textura_ai_tool",
  header: "exp-textura_ai_tool_header",
  headerContent: "exp-textura_ai_tool_header_content",
  headerStatus: "exp-textura_ai_tool_header_status",
  icon: "exp-textura_ai_tool_icon",
  body: "exp-textura_ai_tool_body",
  content: "exp-textura_ai_tool_content",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: AIToolProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AIToolProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    border: `${theme.border.width.sm} solid ${theme.color.border.default}`,
    borderRadius: theme.toRem(theme.border.radius.sm),
    backgroundColor: theme.color.background.default,
    width: "100%",
    display: "flex",
    flexDirection: "column",
    ...theme.typography.body.md,

    [`.${AIToolClasses.header}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[16]),
      padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[16])}`,
      backgroundColor: "transparent",
      cursor: "pointer",
      userSelect: "none",
      minHeight: theme.toRem(40),
      border: "none",
      appearance: "none",
      textAlign: "left",
      fontFamily: "inherit",
      color: "inherit",
      flexWrap: "nowrap",
      width: "100%",
      position: "relative",
      zIndex: 1,
      // When NOT collapsed (i.e. expanded), add border bottom if content follows
      [`.${AIToolClasses.root}[data-expanded='true'] &`]: {
        borderBottom: `${theme.border.width.sm} solid ${theme.color.border.default}`,
        ...styleSlots?.headerExpanded,
      },
      // Rotate icon when expanded (aria-expanded="true")
      [`&[aria-expanded='true'] .${AIToolClasses.icon}`]: {
        transform: "rotate(180deg)",
      },
      ...styleSlots?.header,
    },
    [`.${AIToolClasses.headerContent}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      flex: 1,
      ...theme.typography.label.md,
      ...styleSlots?.headerContent,
    },
    [`.${AIToolClasses.headerStatus}`]: {
      opacity: 0.7,
      fontSize: theme.toRem(12),
      ...styleSlots?.headerStatus,
    },
    [`.${AIToolClasses.icon}`]: {
      color: theme.color.content.icon,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      width: theme.toRem(32),
      height: theme.toRem(32),
      borderRadius: theme.toRem(theme.border.radius.sm),
      transition: "transform 0.2s ease-in-out",
      transform: "rotate(0deg)",
      ...styleSlots?.icon,
    },
    [`.${AIToolClasses.body}`]: {
      overflow: "hidden",
      transition: "max-height 0.2s ease-in-out",
      maxHeight: 0,
      backgroundColor: theme.color.background.default,
      ...styleSlots?.body,
    },
    [`.${AIToolClasses.content}`]: {
      width: "100%",
      padding: theme.toRem(theme.spacing[16]),
      minHeight: 0,
      display: "flex",
      flexDirection: "column",
      gap: theme.toRem(theme.spacing[16]),
      ...styleSlots?.content,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = [...getExcludedDOMProps(), "expanded", "defaultExpanded"];

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledAITool = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<AIToolProps>((props) => generateStyles(props));
